if let source, currentStatus != source {
    return .failure(.invalidTransition)
}

switch (currentStatus, rules.status) {
case (.unopened, .unopened), (.unopened, .inUse), (.inUse, .inUse), (.inUse, .consumed), (.consumed, .consumed):
    break
default:
